create table chb_datacheck_rule_bak as select * from chb_datacheck_rule;
delete from chb_datacheck_rule d WHERE not EXISTS(
select 1 from chb_datacheck_rule_bak b
where datatype like 'CHB_EQUDET%' and d.checkruleid=b.checkruleid);
